fn to_toggle_case(str1: &Vec<char>) -> Vec<char> {
    // Create a new vector to hold the toggled characters
    let mut toggled_vec = Vec::with_capacity(str1.len());

    // Iterate over each character in the input vector
    for &c in str1.iter() {
        // Toggle the case of the character
        let toggled_char = if c.is_ascii_lowercase() {
            // If the character is lowercase, convert it to uppercase
            (c as u8 - b'a' + b'A') as char
        } else if c.is_ascii_uppercase() {
            // If the character is uppercase, convert it to lowercase
            (c as u8 - b'A' + b'a') as char
        } else {
            // If the character is not an ASCII English letter, keep it unchanged
            c
        };
        // Push the toggled character to the new vector
        toggled_vec.push(toggled_char);
    }

    // Return the new vector with toggled characters
    toggled_vec
}